package com.collabcase.sequence;
import java.util.*;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Component;import org.springframework.web.server.ResponseStatusException;
import com.collabcase.ai.context.*;import com.collabcase.sequence.dto.SequenceDefinition;import com.collabcase.sequence.dto.SequenceDefinition.ParticipantType;
@Component public class SequenceDiagramValidator{
 public List<String> validate(SequenceDefinition definition,AiDiagramContext context,String scenario){
  if(scenario==null||scenario.isBlank())throw bad("El escenario es obligatorio");if(definition==null||definition.participants()==null||definition.messages()==null)throw bad("La IA no devolvió una secuencia válida");
  Map<String,AiClassContext>classes=new HashMap<>();context.classes().forEach(item->classes.put(key(item.name()),item));Set<String>ids=new HashSet<>();Map<String,SequenceDefinition.Participant>participants=new HashMap<>();
  for(var participant:definition.participants()){if(participant==null||blank(participant.id())||blank(participant.name())||participant.type()==null)throw bad("Participante incompleto");if(!ids.add(participant.id()))throw bad("Los IDs de participantes deben ser únicos");if(participant.type()==ParticipantType.CLASS&&!classes.containsKey(key(participant.name())))throw bad("La clase de secuencia no existe en el UMLModel: "+participant.name());participants.put(participant.id(),participant);}
  List<String>warnings=new ArrayList<>();int previous=0;for(var message:definition.messages().stream().sorted(Comparator.comparingInt(m->m.order()==null?-1:m.order())).toList()){if(message==null||message.order()==null||message.order()<=previous)throw bad("El orden de mensajes debe ser positivo, único y ascendente");previous=message.order();if(!participants.containsKey(message.from())||!participants.containsKey(message.to()))throw bad("Todo mensaje debe referenciar participantes existentes");if(blank(message.label())||message.kind()==null)throw bad("Mensaje incompleto");var target=participants.get(message.to());String method=method(message.label());if(method!=null&&target.type()==ParticipantType.CLASS){var targetClass=classes.get(key(target.name()));if(!targetClass.methods().isEmpty()&&targetClass.methods().stream().noneMatch(m->key(m.name()).equals(key(method))))warnings.add("El método '"+method+"' no está modelado en "+target.name()+".");}}
  return List.copyOf(warnings);
 }
 private String method(String label){int open=label.indexOf('(');return open>0?label.substring(0,open).trim():null;}private String key(String value){return value==null?"":value.trim().toLowerCase(Locale.ROOT);}private boolean blank(String value){return value==null||value.isBlank();}private ResponseStatusException bad(String message){return new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,message);}
}
